import{_ as p,a0 as l,w as o,s as h,I as a,x as n,a1 as t,A as i,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"使用 C 優化你的 Python 代碼 | LCTT x X-CMD","titleTemplate":false,"description":"使用 C 優化你的 Python 代碼 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 C 優化你的 Python 代碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 C 優化你的 Python 代碼 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210421 Optimize your Python code with C","title":"使用 C 優化你的 Python 代碼","tag":"202104","desc":""},"relativePath":"202104/20210421 Optimize your Python code with C.md","filePath":"[post].md"}'),d={name:"202104/20210421 Optimize your Python code with C.md"};function c(g,s,u,y,b,k){const e=l("Link");return o(),h("div",null,[s[18]||(s[18]=a("h1",{id:"使用-c-優化你的-python-代碼",tabindex:"-1"},[n("使用 C 優化你的 Python 代碼 "),a("a",{class:"header-anchor",href:"#使用-c-優化你的-python-代碼","aria-label":"Permalink to “使用 C 優化你的 Python 代碼”"},"​")],-1)),s[19]||(s[19]=a("blockquote",null,[a("p",null,"Cython 創建的 C 模組可以加速 Python 代碼的執行，這對使用效率不高的解釋型語言編寫的複雜應用是很重要的。")],-1)),s[20]||(s[20]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/26/230709qz64z4af3t9b9jab.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("Cython 是 Python 編程語言的編譯器，旨在優化性能並形成一個擴展的 Cython 編程語言。作為 Python 的擴展，",-1)),t(e,{href:"https://cython.org/"},{default:i(()=>[...s[0]||(s[0]=[n("Cython",-1)])]),_:1}),s[2]||(s[2]=n(" 也是 Python 語言的超集，它支持調用 C 函數和在變量和類屬性上聲明 C 類型。這使得包裝外部 C 庫、將 C 嵌入現有應用程序或者為 Python 編寫像 Python 一樣簡單的 C 語言擴展語法變得容易。",-1))]),s[21]||(s[21]=r(`<p>Cython 一般用於創建 C 模組來加速 Python 代碼的執行。這在使用解釋型語言編寫的效率不高的複雜應用中非常重要。</p><h3 id="安裝-cython" tabindex="-1">安裝 Cython <a class="header-anchor" href="#安裝-cython" aria-label="Permalink to “安裝 Cython”">​</a></h3><p>你可以在 Linux、BSD、Windows 或 macOS 上安裝 Cython 來使用 Python：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python -m pip install Cython</span></span></code></pre></div><p>安裝好後，就可以使用它了。</p><h3 id="將-python-轉換成-c" tabindex="-1">將 Python 轉換成 C <a class="header-anchor" href="#將-python-轉換成-c" aria-label="Permalink to “將 Python 轉換成 C”">​</a></h3><p>使用 Cython 的一個好的方式是從一個簡單的 “hello world” 開始。這雖然不是展示 Cython 優點的最好方式，但是它展示了使用 Cython 時發生的情況。</p><p>首先，創建一個簡單的 Python 腳本，文件命名為 <code>hello.pyx</code>（<code>.pyx</code> 擴展名並不神奇，從技術上它可以是任何東西，但它是 Cython 的默認擴展名）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print(&quot;hello world&quot;)</span></span></code></pre></div><p>接下來，創建一個 Python 設置腳本。一個像 Python 的 makefile 一樣的 <code>setup.py</code>，Cython 可以使用它來處理你的 Python 代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from setuptools import setup</span></span>
<span class="line"><span>from Cython.Build import cythonize</span></span>
<span class="line"><span></span></span>
<span class="line"><span>setup(</span></span>
<span class="line"><span>    ext_modules = cythonize(&quot;hello.pyx&quot;)</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>最後，使用 Cython 將你的 Python 腳本轉換為 C 代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python setup.py build_ext --inplace</span></span></code></pre></div><p>你可以在你的工程目錄中看到結果。Cython 的 <code>cythonize</code> 模組將 <code>hello.pyx</code> 轉換成一個 <code>hello.c</code> 文件和一個 <code>.so</code> 庫。這些 C 代碼有 2648 行，所以它比一個一行的 <code>hello.pyx</code> 源碼的文本要多很多。<code>.so</code> 庫也比它的源碼大 2000 倍（即 54000 字節和 20 字節相比）。然後，Python 需要運行單個 Python 腳本，所以有很多代碼支持這個只有一行的 <code>hello.pyx</code> 文件。</p><p>要使用 Python 的 “hello world” 腳本的 C 代碼版本，請打開一個 Python 提示符並導入你創建的新 <code>hello</code> 模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import hello</span></span>
<span class="line"><span>hello world</span></span></code></pre></div><h3 id="將-c-代碼集成到-python-中" tabindex="-1">將 C 代碼集成到 Python 中 <a class="header-anchor" href="#將-c-代碼集成到-python-中" aria-label="Permalink to “將 C 代碼集成到 Python 中”">​</a></h3><p>測試計算能力的一個很好的通用測試是計算質數。質數是一個比 1 大的正數，且它只有被 1 或它自己除後才會產生正整數。雖然理論很簡單，但是隨着數的變大，計算需求也會增加。在純 Python 中，可以用 10 行以內的代碼完成質數的計算。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>number = int(sys.argv[1])</span></span>
<span class="line"><span>if not number &lt;= 1:</span></span>
<span class="line"><span>    for i in range(2, number):</span></span>
<span class="line"><span>        if (number % i) == 0:</span></span>
<span class="line"><span>            print(&quot;Not prime&quot;)</span></span>
<span class="line"><span>            break</span></span>
<span class="line"><span>else:</span></span>
<span class="line"><span>    print(&quot;Integer must be greater than 1&quot;)</span></span></code></pre></div><p>這個腳本在成功的時候是不會提醒的，如果這個數不是質數，則返回一條信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./prime.py 3</span></span>
<span class="line"><span>$ ./prime.py 4</span></span>
<span class="line"><span>Not prime.</span></span></code></pre></div><p>將這些轉換為 Cython 需要一些工作，一部分是為了使代碼適合用作庫，另一部分是為了提高性能。</p><h4 id="腳本和庫" tabindex="-1">腳本和庫 <a class="header-anchor" href="#腳本和庫" aria-label="Permalink to “腳本和庫”">​</a></h4><p>許多用户將 Python 當作一種腳本語言來學習：你告訴 Python 想讓它執行的步驟，然後它來做。隨着你對 Python（以及一般的開源編程）的瞭解越多，你可以瞭解到許多強大的代碼都存在於其他應用程序可以利用的庫中。你的代碼越 <em>不具有針對性</em>，程序員（包括你）就越可能將其重用於其他的應用程序。將計算和工作流解耦可能需要更多的工作，但最終這通常是值得的。</p><p>在這個簡單的質數計算的例子中，將其轉換成 Cython，首先是一個設置腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from setuptools import setup</span></span>
<span class="line"><span>from Cython.Build import cythonize</span></span>
<span class="line"><span></span></span>
<span class="line"><span>setup(</span></span>
<span class="line"><span>    ext_modules = cythonize(&quot;prime.py&quot;)</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>將你的腳本轉換成 C：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python setup.py build_ext --inplace</span></span></code></pre></div><p>到目前為止，一切似乎都工作的很好，但是當你試圖導入並使用新模組時，你會看到一個錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import prime</span></span>
<span class="line"><span>Traceback (most recent call last):</span></span>
<span class="line"><span>  File &quot;&lt;stdin&gt;&quot;, line 1, in &lt;module&gt;</span></span>
<span class="line"><span>  File &quot;prime.py&quot;, line 2, in init prime</span></span>
<span class="line"><span>    number = sys.argv[1]</span></span>
<span class="line"><span>IndexError: list index out of range</span></span></code></pre></div><p>這個問題是 Python 腳本希望從一個終端運行，其中參數（在這個例子中是要測試是否為質數的整數）是一樣的。你需要修改你的腳本，使它可以作為一個庫來使用。</p><h4 id="寫一個庫" tabindex="-1">寫一個庫 <a class="header-anchor" href="#寫一個庫" aria-label="Permalink to “寫一個庫”">​</a></h4><p>庫不使用系統參數，而是接受其他代碼的參數。對於用户輸入，與其使用 <code>sys.argv</code>，不如將你的代碼封裝成一個函數來接收一個叫 <code>number</code>（或者 <code>num</code>，或者任何你喜歡的變量名）的參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def calculate(number):</span></span>
<span class="line"><span>    if not number &lt;= 1:</span></span>
<span class="line"><span>        for i in range(2, number):</span></span>
<span class="line"><span>            if (number % i) == 0:</span></span>
<span class="line"><span>                print(&quot;Not prime&quot;)</span></span>
<span class="line"><span>                break</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        print(&quot;Integer must be greater than 1&quot;)</span></span></code></pre></div><p>這確實使你的腳本有些難以測試，因為當你在 Python 中運行代碼時，<code>calculate</code> 函數永遠不會被執行。但是，Python 編程人員已經為這個問題設計了一個通用、還算直觀的解決方案。當 Python 解釋器執行一個 Python 腳本時，有一個叫 <code>__name__</code> 的特殊變量，這個變量被設置為 <code>__main__</code>，但是當它被作為模組導入的時候，<code>__name__</code> 被設置為模組的名字。利用這點，你可以寫一個既是 Python 模組又是有效 Python 腳本的庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def calculate(number):</span></span>
<span class="line"><span>    if not number &lt;= 1:</span></span>
<span class="line"><span>        for i in range(2, number):</span></span>
<span class="line"><span>            if (number % i) == 0:</span></span>
<span class="line"><span>                print(&quot;Not prime&quot;)</span></span>
<span class="line"><span>                break</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        print(&quot;Integer must be greater than 1&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    number = sys.argv[1]    </span></span>
<span class="line"><span>    calculate( int(number) )</span></span></code></pre></div><p>現在你可以用一個命令來運行代碼了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python ./prime.py 4</span></span>
<span class="line"><span>Not a prime</span></span></code></pre></div><p>你可以將它轉換為 Cython 來用作一個模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import prime</span></span>
<span class="line"><span>&gt;&gt;&gt; prime.calculate(4)</span></span>
<span class="line"><span>Not prime</span></span></code></pre></div><h3 id="c-python" tabindex="-1">C Python <a class="header-anchor" href="#c-python" aria-label="Permalink to “C Python”">​</a></h3><p>用 Cython 將純 Python 的代碼轉換為 C 代碼是有用的。這篇文章描述瞭如何做，然而，Cython 還有功能可以幫助你在轉換之前優化你的代碼，分析你的代碼來找到 Cython 什麼時候與 C 進行交互，以及更多。如果你正在用 Python，但是你希望用 C 代碼改進你的代碼，或者進一步理解庫是如何提供比腳本更好的擴展性的，或者你只是好奇 Python 和 C 是如何協作的，那麼就開始使用 Cython 吧。</p><hr>`,43)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),t(e,{href:"https://opensource.com/article/21/4/cython"},{default:i(()=>[...s[3]||(s[3]=[n("https://opensource.com/article/21/4/cython",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=n("作者：",-1)),t(e,{href:"https://opensource.com/users/alansmithee"},{default:i(()=>[...s[5]||(s[5]=[n("Alan Smithee",-1)])]),_:1}),s[10]||(s[10]=n(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 譯者：",-1)),t(e,{href:"https://github.com/ShuyRoy"},{default:i(()=>[...s[7]||(s[7]=[n("ShuyRoy",-1)])]),_:1}),s[12]||(s[12]=n(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[n("Linux中國",-1)])]),_:1}),s[17]||(s[17]=n(" 榮譽推出",-1))])])}const P=p(d,[["render",c]]);export{f as __pageData,P as default};
